INSERT INTO editorial_documents ("id", "document_type", "locale", "schema_version", "document", "status", "owner_artist_id", "created_at", "updated_at", "revision")
VALUES ('43012fe8-f0eb-44ab-86b2-1da4446a5bdb', 'artist_biography', 'en', 1, '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Tito Chicoma is a Dominican artist. The artist is connected to Santo Domingo, with work tied to Dominican music culture and its wider audience.","type":"text"}]}]}'::jsonb, 'published', '54e1f08f-8843-4abb-b117-dc4fc7490a97', '2026-08-06T02:52:19.958Z', '2026-08-06T02:52:19.958Z', 1);

-- Luis Aquino (luis-aquino)

INSERT INTO artists ("id", "name", "sort_name", "type", "birth_year", "death_year", "created_at", "views", "wikidata_id", "first_name", "middle_name", "last_name", "second_last_name", "stage_name", "date_of_birth", "birth_place", "website", "youtube", "facebook", "instagram", "aliases", "mbid", "occupations", "instruments", "genres", "disambiguation", "gender", "ended", "mb_metadata", "updated_at", "province", "slug", "primary_role", "artist_tags", "date_of_death", "status", "primary_genre", "bio_en", "bio_es", "has_image", "image_updated_at")
VALUES ('7da4869c-bffe-4a72-ba92-5b5d72dafe4f', 'Luis Aquino', 'Aquino, Luis', 'solo_artist', NULL, NULL, '2026-05-16T01:20:08.033Z', 0, NULL, 'Luis', NULL, 'Aquino', NULL, 'Luis Aquino', NULL, 'San Juan', NULL, NULL, NULL, NULL, ARRAY[]::text[], 'ff8af33f-f31c-4d44-b105-114eea195618', '["musician"]'::jsonb, ARRAY[]::text[], ARRAY['salsa']::text[], NULL, 'male', FALSE, '{"id":"ff8af33f-f31c-4d44-b105-114eea195618","area":{"id":"696cb3e0-5084-30ab-9916-65ece70adbf6","name":"Dominican Republic","type":"Country","type-id":"06dd0ae4-8c74-30bb-b43d-95dcedf961de","life-span":{"ended":null},"sort-name":"Dominican Republic"},"name":"Luis Aquino","type":"Person","score":73,"gender":"male","country":"DO","type-id":"b6e035f4-3ce9-331c-97df-83397230b0df","gender-id":"36d3d30a-839d-3eda-8cb3-29be4384e4a9","life-span":{"ended":null},"sort-name":"Aquino, Luis","disambiguation":"Trumpet player"}'::jsonb, '2026-08-22T21:26:37.807Z', 'No Province', 'luis-aquino', 'instrumentalist', ARRAY['secular', 'legend']::text[], NULL, 'needs_review', 'merengue', 'Luis Aquino is a musician connected to the Dominican Republic whose work in merengue, salsa, tropical, and pop reflects a broad engagement with the Caribbean popular music tradition. His connection to San Juan — whether referring to the Dominican municipality or suggesting a connection to the Puerto Rican capital that is a hub of salsa culture — places him within the pan-Caribbean musical conversation in which Dominican musicians have always participated. Aquino''s work across merengue, salsa, and tropical demonstrates the fluid musical dialogue between Dominican and broader Caribbean popular traditions, and his engagement with pop suggests an artist aware of the international market for Latin music and its potential to carry Caribbean sounds to global audiences.', NULL, FALSE, NULL);

