VALUES ('f9ba3906-75b3-444e-8654-7693c39b89cf', 'artist_biography', 'en', 1, '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Luis Aquino is a musician connected to the Dominican Republic whose work in merengue, salsa, tropical, and pop reflects a broad engagement with the Caribbean popular music tradition. His connection to San Juan — whether referring to the Dominican municipality or suggesting a connection to the Puerto Rican capital that is a hub of salsa culture — places him within the pan-Caribbean musical conversation in which Dominican musicians have always participated. Aquino''s work across merengue, salsa, and tropical demonstrates the fluid musical dialogue between Dominican and broader Caribbean popular traditions, and his engagement with pop suggests an artist aware of the international market for Latin music and its potential to carry Caribbean sounds to global audiences.","type":"text"}]}]}'::jsonb, 'published', '7da4869c-bffe-4a72-ba92-5b5d72dafe4f', '2026-08-06T02:52:19.958Z', '2026-08-06T02:52:19.958Z', 1);

